package vn.hust.restaurant.service;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.DiningTable;import vn.hust.restaurant.repository.TableRepository;public class TableService{private final TableRepository r;public TableService(TableRepository r){this.r=r;}public List<DiningTable>all()throws SQLException{return r.findAll();}public void save(DiningTable t)throws SQLException{if(t.code().isBlank()||t.name().isBlank()||t.capacity()<=0)throw new IllegalArgumentException("Mã, tên và sức chứa bàn không hợp lệ");r.save(t);}public void deactivate(int id)throws SQLException{r.deactivate(id);}}
